// LIVE API DATA LAYER
// Connects to http://localhost:8000 — falls back to MOCK if offline
// operator_id: default "op_beach_habitats" (set to your company UUID)
// ═══════════════════════════════════════════════════════════════════
const API_BASE = "http://localhost:8000/api/v1";
const DEFAULT_OPERATOR = "op_beach_habitats";

async function apiFetch(path, fallback = null) {
  try {
    const r = await fetch(`${API_BASE}${path}`, {
      headers: { "Content-Type": "application/json" },
      signal: AbortSignal.timeout(4000),
    });
    if (!r.ok) return fallback;
    return await r.json();
  } catch {
    return fallback;
  }
}

function useOyvodaApi(operatorId = DEFAULT_OPERATOR) {
  const [apiData, setApiData] = useState(null);
  const [live, setLive] = useState(false);
  const [loading, setLoading] = useState(true);
  const [lastFetch, setLastFetch] = useState(null);

  const fetchAll = async () => {
    const [stats, escalations, gaps, preBooking, analytics, properties, orphans, heatmap, revenue, incidents, incidentSummary] = await Promise.all([
      apiFetch(`/operator/stats?operator_id=${operatorId}`),
      apiFetch(`/operator/escalations?operator_id=${operatorId}`),
      apiFetch(`/operator/knowledge-gaps?operator_id=${operatorId}&resolved=false&limit=20`),
      apiFetch(`/inquiries?company_id=${operatorId}&status=pending_review`),
      apiFetch(`/operator/analytics?operator_id=${operatorId}&days=30`),
      apiFetch(`/operator/analytics/properties?operator_id=${operatorId}&days=30`),
      apiFetch(`/orphans?company_id=${operatorId}&status=unresolved`),
      apiFetch(`/operator/analytics/heatmap?operator_id=${operatorId}&days=90`),
      apiFetch(`/operator/analytics/revenue?operator_id=${operatorId}&months=6`),
      apiFetch(`/incidents?company_id=${operatorId}&limit=50`),
      apiFetch(`/incidents/summary?company_id=${operatorId}`),
    ]);

    const anyLive = [stats, escalations, gaps, analytics].some(d => d !== null);
    setLive(anyLive);

    if (anyLive) {
      setApiData({ stats, escalations, gaps, preBooking, analytics, properties, orphans, heatmap, revenue, incidents, incidentSummary });
    }
    setLoading(false);
    setLastFetch(new Date());
  };

  useEffect(() => {
    fetchAll();
    const interval = setInterval(fetchAll, 60_000); // refresh every 60s
    return () => clearInterval(interval);
  }, [operatorId]);

  // Merge live data over MOCK — live wins, MOCK fills gaps
  const merged = {
    stats: apiData?.stats ? {
      sessions: apiData.stats.total_sessions ?? MOCK.stats.sessions,
      arriving: apiData.stats.arriving_today ?? MOCK.stats.arriving,
      inStay: apiData.stats.in_stay ?? MOCK.stats.inStay,
      escalations: apiData.stats.pending_escalations ?? MOCK.stats.escalations,
      conversations: apiData.stats.total_conversations ?? MOCK.stats.conversations,
      rcsDelivered: MOCK.stats.rcsDelivered,
    } : MOCK.stats,

    escalations: apiData?.escalations?.length
      ? apiData.escalations.map(e => ({
          id: e.id,
          guest: e.guest_name,
          property: e.property_name,
          issue: e.summary || e.reason,
          priority: e.priority,
          time: new Date(e.created_at).toLocaleString("en-US", {hour:"2-digit", minute:"2-digit"}),
          vendor: null,
          eta: null,
          geoAlert: e.priority === "urgent",
        }))
      : MOCK.escalations,

    kbGaps: apiData?.gaps?.length
      ? apiData.gaps.map((g, i) => ({
          id: g.gap_id,
          q: g.question_text,
          count: 1,
          trend: "stable",
          suggested: g.resolution_notes || "",
          category: g.detected_intent || "general",
          severity: g.confidence_score > 0.8 ? "high" : "medium",
          lastAsked: new Date(g.created_at).toLocaleString(),
          scope: g.property_external_id ? `Property ${g.property_external_id}` : "All Properties",
          askTimes: [],
        }))
      : MOCK.kbGaps,

    preBooking: apiData?.preBooking?.inquiries?.length
      ? apiData.preBooking.inquiries.map(inq => ({
          id: inq.draft_id,
          platform: inq.platform,
          property: inq.property_id || "Unknown",
          q: inq.message,
          time: new Date(inq.received_at).toLocaleString(),
          status: inq.status === "pending_review" ? "pending" : inq.status,
          draft: inq.draft_text,
        }))
      : MOCK.preBooking,

    analytics: apiData?.analytics,

    weekly: apiData?.analytics?.daily_volumes?.slice(-7).map((d, i) => ({
      day: ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][new Date(d.date).getDay()],
      rcs: d.inbound + d.outbound,
      resolved: d.quick,
      escalated: 0,
      vendorRefs: 0,
      upsells: 0,
      eventInq: 0,
    })) || MOCK.weekly,

    revenue: apiData?.revenue?.monthly?.map(m => ({
      month: m.month?.slice(5) || m.month,
      staff: Math.round(m.staff_value_usd),
      upsell: Math.round(m.upsell_value_usd),
      vendor: 0,
      events: 0,
      total: Math.round(m.total_value_usd),
    })) || MOCK.revenue,

    heatmap: apiData?.heatmap?.cells?.length ? apiData.heatmap.cells : MOCK.heatmap,

    // Incidents — live from property_incidents table
    incidents: apiData?.incidents?.incidents?.length
      ? apiData.incidents.incidents
      : MOCK_INCIDENTS,

    incidentSummary: apiData?.incidentSummary || { active_count: 0, urgent_count: 0 },

    // These stay as MOCK for now (no live endpoint yet)
    guestCalls: MOCK.guestCalls,
    vendors: MOCK.vendors,
    monthly: apiData?.analytics?.daily_volumes?.length
      ? apiData.analytics.daily_volumes.map(d => ({
          date: d.date,
          rcs: d.inbound + d.outbound,
          resolved: d.quick,
          csat: 4.5,
          vendorRefs: 0,
          upsell: 0,
          staffHrs: 0,
          eventInq: 0,
        }))
      : MOCK.monthly,
    sentiment: MOCK.sentiment,
    health: apiData?.analytics ? {
      resolutionRate: Math.round((apiData.analytics.quick_answer_rate || 0.89) * 100),
      avgCsat: 92,
      responseSpeed: apiData.analytics.avg_response_ms < 1000 ? 96 : 88,
      escalationRate: 96,
      kbCoverage: 82,
      guestEngagement: 88,
      vendorUtil: 76,
      returningGuest: 71,
    } : MOCK.health,
    referralFunnel: LIVE.referralFunnel,
  };

  return { data: merged, live, loading, lastFetch, refetch: fetchAll };
}


