      <div style={{flex:1}}><div style={{fontSize:11,fontWeight:700,color:T.white}}>{d.status.label}</div><div style={{fontSize:10,color:T.dim,marginTop:1,lineHeight:1.4}}>{d.narrative.slice(0,110)}…</div></div>
