                {!e.managed&&e.properties&&<span style={{fontSize:8,padding:"1px 6px",borderRadius:100,background:"rgba(200,120,50,0.1)",color:T.gold}}>{e.properties==="All Properties"?"All Properties":e.properties}</span>}
                <span style={{fontSize:8,padding:"1px 6px",borderRadius:100,background:`${catColor[e.category]||T.muted}22`,color:catColor[e.category]||T.ghost}}>{e.category}</span>
