  const enableAll = () => setProperties(p=>p.map(pr=>({...pr,enabled:true,enabledAt:pr.enabledAt||"Today"})));

  const alertTypes = ["All Alerts","Maintenance","Escalation / Complaint","Pre-Booking","KB Gaps","Safety","Billing"];
