function QueueV2Button({ variant="secondary", size="md", children, onClick, disabled, style }) {
  const variants = {
    primary:{background:QV2.brand600,color:QV2.textInverse,border:`1px solid ${QV2.brand600}`,hoverBg:QV2.brand500},
    secondary:{background:QV2.surfaceRaised,color:QV2.textPrimary,border:`1px solid ${QV2.borderDefault}`,hoverBg:QV2.surfaceSunken},
    ghost:{background:"transparent",color:QV2.textPrimary,border:"1px solid transparent",hoverBg:QV2.surfaceSunken},
  };
  const sizes = {
    sm:{height:28,padding:"0 10px",fontSize:12},
    md:{height:36,padding:"0 14px",fontSize:14},
    lg:{height:44,padding:"0 20px",fontSize:14},
  };
  const v = variants[variant];
  const s = sizes[size];
  const [hover, setHover] = useState(false);
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      onMouseEnter={()=>setHover(true)}
      onMouseLeave={()=>setHover(false)}
      style={{
        height:s.height,padding:s.padding,fontSize:s.fontSize,fontFamily:QV2.fontSans,fontWeight:500,
        background:hover && !disabled ? v.hoverBg : v.background,color:v.color,border:v.border,borderRadius:QV2.radiusMd,
        cursor:disabled?"not-allowed":"pointer",opacity:disabled?0.5:1,display:"inline-flex",alignItems:"center",
        justifyContent:"center",gap:6,transition:"background 100ms",whiteSpace:"nowrap",...style
      }}
    >
      {children}
    </button>
  );
}

