function queueV2FormatTime(iso) {
  const d = new Date(iso);
  const now = new Date();
  const diffMs = now - d;
  const diffMin = Math.floor(diffMs / 60000);
  const diffHr = Math.floor(diffMin / 60);
  if (diffMin < 1) return "just now";
  if (diffMin < 60) return `${diffMin}m ago`;
  if (diffHr < 24) return d.toLocaleTimeString([], { hour:"numeric", minute:"2-digit" });
  return d.toLocaleDateString([], { month:"short", day:"numeric" });
}

function queueV2ActionLabel(action) {
  switch (action) {
    case "AUTO_SEND": return { label:"Auto-send ready", tone:"success" };
    case "CLARIFY": return { label:"Clarification", tone:"info" };
    case "DRAFT_ONLY": return { label:"Review draft", tone:"warning" };
    case "ESCALATE": return { label:"Escalate", tone:"danger" };
    default: return { label:"Unknown", tone:"default" };
  }
}

