function QueueV2List({ inquiries, selectedId, onSelect, filter, setFilter }) {
  const filters = [
    {id:"all",label:"All",count:inquiries.length},
    {id:"clarify",label:"Needs clarification",count:inquiries.filter((i)=>i.aiAction==="CLARIFY").length},
    {id:"ready",label:"Ready to send",count:inquiries.filter((i)=>i.aiAction==="AUTO_SEND").length},
    {id:"review",label:"Review carefully",count:inquiries.filter((i)=>i.aiAction==="DRAFT_ONLY").length},
  ];
  const filtered = useMemo(()=>{
    if (filter === "all") return inquiries;
    const map = {clarify:"CLARIFY",ready:"AUTO_SEND",review:"DRAFT_ONLY"};
    return inquiries.filter((i)=>i.aiAction===map[filter]);
  }, [inquiries, filter]);
  return (
    <div style={{flex:1,background:QV2.surfacePage,display:"flex",flexDirection:"column",minWidth:0}}>
      <div style={{padding:"20px 24px 0",background:QV2.surfacePage,borderBottom:`1px solid ${QV2.borderHairline}`}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div>
            <h1 style={{fontSize:22,fontWeight:600,color:QV2.textPrimary,margin:0,letterSpacing:"-0.01em"}}>Review queue</h1>
            <div style={{fontSize:13,color:QV2.textSecondary,marginTop:4}}>{inquiries.length} inquiries waiting · last auto-sent 2 hours ago</div>
          </div>
          <div style={{display:"flex",gap:8}}>
            <QueueV2Button variant="secondary" size="sm">⌘K Search</QueueV2Button>
            <QueueV2Button variant="primary" size="sm">Bulk actions</QueueV2Button>
          </div>
        </div>
        <div style={{display:"flex",gap:4,marginTop:16,marginBottom:-1}}>
          {filters.map((f)=>{
            const isActive = filter === f.id;
            return (
              <button key={f.id} onClick={()=>setFilter(f.id)} style={{padding:"8px 14px",background:"transparent",border:"none",borderBottom:`2px solid ${isActive?QV2.brand600:"transparent"}`,fontSize:13,fontWeight:isActive?600:400,color:isActive?QV2.textPrimary:QV2.textSecondary,cursor:"pointer",fontFamily:QV2.fontSans,display:"flex",alignItems:"center",gap:6}}>
                {f.label}
                <span style={{fontSize:11,fontWeight:500,color:QV2.textTertiary,fontVariantNumeric:"tabular-nums"}}>{f.count}</span>
              </button>
            );
          })}
        </div>
      </div>
      <div style={{flex:1,overflowY:"auto"}}>
        {filtered.length===0 ? <QueueV2EmptyState title="You're caught up" description="No inquiries match this filter. Last auto-sent 2 hours ago to Maria Hernandez at Sea La Vie." /> : filtered.map((inquiry)=><QueueV2Row key={inquiry.id} inquiry={inquiry} selected={inquiry.id===selectedId} onClick={()=>onSelect(inquiry)} />)}
      </div>
    </div>
  );
}

function QueueV2DetailPanel({ inquiry, onClose, onApprove, onEdit, onReject, onDismiss }) {
  const [editing, setEditing] = useState(false);
  const [draftText, setDraftText] = useState(inquiry?.aiDraft || "");
  useEffect(()=>{ setDraftText(inquiry?.aiDraft || ""); setEditing(false); }, [inquiry?.id]);
  if (!inquiry) return null;
  const action = queueV2ActionLabel(inquiry.aiAction);
  const isClarify = inquiry.aiAction === "CLARIFY";
  return (
    <aside style={{width:460,background:QV2.surfaceRaised,borderLeft:`1px solid ${QV2.borderDefault}`,display:"flex",flexDirection:"column",height:"100vh",position:"sticky",top:0,overflow:"hidden",animation:"slideIn 200ms cubic-bezier(0.2, 0, 0, 1)",flexShrink:0}}>
      <div style={{padding:"18px 20px",borderBottom:`1px solid ${QV2.borderHairline}`,display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:12}}>
        <div style={{minWidth:0,flex:1}}>
          <div style={{fontSize:16,fontWeight:600,color:QV2.textPrimary,marginBottom:2}}>{inquiry.guestName}</div>
          <div style={{fontSize:12,color:QV2.textTertiary}}>{inquiry.guestEmail}</div>
        </div>
        <button onClick={onClose} style={{width:28,height:28,border:"none",background:"transparent",color:QV2.textTertiary,cursor:"pointer",fontSize:18,borderRadius:QV2.radiusSm,flexShrink:0}} aria-label="Close">×</button>
      </div>
      <div style={{padding:"14px 20px",background:QV2.surfaceSunken,borderBottom:`1px solid ${QV2.borderHairline}`}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:13,fontWeight:500,color:QV2.textPrimary}}>{inquiry.propertyName}</span>
            <span style={{fontSize:11,color:QV2.textTertiary,fontFamily:QV2.fontMono}}>{inquiry.propertyCode}</span>
          </div>
          <QueueV2Badge tone={inquiry.approvalMode==="auto"?"brand":"default"}>{inquiry.approvalMode}</QueueV2Badge>
        </div>
        <div style={{fontSize:12,color:QV2.textSecondary,lineHeight:1.5}}>
          {Object.entries(inquiry.propertyFacts).slice(0, 3).map(([k,v])=>`${k}: ${v}`).join(" · ")}
        </div>
      </div>
      <div style={{flex:1,overflowY:"auto"}}>
        <div style={{padding:"18px 20px 16px"}}>
          <div style={{fontSize:11,fontWeight:500,letterSpacing:"0.04em",textTransform:"uppercase",color:QV2.textTertiary,marginBottom:8}}>Guest message · {queueV2FormatTime(inquiry.receivedAt)}</div>
          <div style={{fontSize:14,color:QV2.textPrimary,lineHeight:1.6,padding:14,background:QV2.surfaceSunken,borderRadius:QV2.radiusMd,border:`1px solid ${QV2.borderHairline}`}}>{inquiry.message}</div>
        </div>
        <div style={{padding:"0 20px 12px"}}>
          <div style={{display:"flex",alignItems:"center",gap:8,padding:"10px 12px",background:QV2.info50,borderRadius:QV2.radiusMd,border:`1px solid ${QV2.borderHairline}`}}>
            <QueueV2Badge tone={action.tone}>{action.label}</QueueV2Badge>
            <span style={{fontSize:12,color:QV2.textSecondary}}>{isClarify ? "Ambiguous — ask before answering" : `Confidence ${Math.round(inquiry.confidence * 100)}%`}</span>
          </div>
        </div>
        <div style={{padding:"0 20px 20px"}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
            <div style={{fontSize:11,fontWeight:500,letterSpacing:"0.04em",textTransform:"uppercase",color:QV2.textTertiary}}>{isClarify && !inquiry.aiDraft ? "Suggested questions" : "AI draft reply"}</div>
            {!editing && inquiry.aiDraft && <button onClick={()=>setEditing(true)} style={{background:"transparent",border:"none",fontSize:12,color:QV2.brand600,cursor:"pointer",padding:"2px 4px",fontWeight:500}}>Edit</button>}
          </div>
          {isClarify && !inquiry.aiDraft && inquiry.clarificationQuestions ? (
            <div style={{fontSize:14,color:QV2.textPrimary,lineHeight:1.6,padding:14,background:QV2.info50,borderRadius:QV2.radiusMd,border:"1px solid #bfdbfe"}}>
              {inquiry.clarificationQuestions.map((q, i)=><div key={i} style={{marginBottom:i<inquiry.clarificationQuestions.length-1?8:0}}>• {q}</div>)}
            </div>
          ) : editing ? (
            <textarea value={draftText} onChange={(e)=>setDraftText(e.target.value)} style={{width:"100%",minHeight:160,fontSize:14,lineHeight:1.6,fontFamily:QV2.fontSans,color:QV2.textPrimary,padding:14,background:QV2.surfaceRaised,border:`1px solid ${QV2.borderFocus}`,borderRadius:QV2.radiusMd,outline:"none",resize:"vertical",boxSizing:"border-box"}} />
          ) : (
            <div style={{fontSize:14,color:QV2.textPrimary,lineHeight:1.6,padding:14,background:QV2.surfaceRaised,borderRadius:QV2.radiusMd,border:`1px solid ${QV2.borderDefault}`}}>
              {inquiry.aiDraft || <span style={{color:QV2.textTertiary,fontStyle:"italic"}}>No draft generated — review guest message and reply manually.</span>}
            </div>
          )}
        </div>
      </div>
      <div style={{padding:"12px 16px",borderTop:`1px solid ${QV2.borderDefault}`,background:QV2.surfaceRaised,display:"flex",gap:8,alignItems:"center"}}>
        <QueueV2Button variant="ghost" size="md" onClick={onDismiss}>Dismiss</QueueV2Button>
        <QueueV2Button variant="ghost" size="md" onClick={onReject} style={{color:QV2.danger600}}>Reject</QueueV2Button>
        <div style={{flex:1}} />
        {editing ? (
          <>
            <QueueV2Button variant="secondary" size="md" onClick={()=>setEditing(false)}>Cancel</QueueV2Button>
            <QueueV2Button variant="primary" size="md" onClick={()=>onEdit(draftText)}>Send edited</QueueV2Button>
          </>
        ) : (
          <QueueV2Button variant="primary" size="md" onClick={onApprove}>{isClarify ? "Send questions" : "Approve & send"}</QueueV2Button>
        )}
      </div>
    </aside>
  );
}

function QueueReviewPage({ setPage }) {
  const [inquiries, setInquiries] = useState(queueV2MockInquiries);
  const [selectedId, setSelectedId] = useState(null);
  const [filter, setFilter] = useState("all");
  const selected = inquiries.find((i)=>i.id===selectedId) || null;
  const removeInquiry = (id) => {
    setInquiries((arr)=>arr.filter((i)=>i.id!==id));
    setSelectedId(null);
  };
  return (
    <div style={{display:"flex",minHeight:"100vh",background:QV2.surfacePage,fontFamily:QV2.fontSans,color:QV2.textPrimary,fontSize:14,lineHeight:1.5}}>
      <QueueV2Sidebar />
      <QueueV2List inquiries={inquiries} selectedId={selectedId} onSelect={(inq)=>setSelectedId(inq.id)} filter={filter} setFilter={setFilter} />
      {selected && (
        <QueueV2DetailPanel
          inquiry={selected}
          onClose={()=>setSelectedId(null)}
          onApprove={()=>removeInquiry(selected.id)}
          onEdit={()=>removeInquiry(selected.id)}
          onReject={()=>removeInquiry(selected.id)}
          onDismiss={()=>removeInquiry(selected.id)}
        />
      )}
      <button onClick={()=>setPage("home")} style={{position:"fixed",top:14,right:16,zIndex:1100,background:"rgba(10,10,10,0.82)",color:"#fff",border:"1px solid rgba(255,255,255,0.18)",borderRadius:999,padding:"8px 14px",fontSize:12,fontWeight:600,cursor:"pointer",backdropFilter:"blur(10px)"}}>← Back to dashboard</button>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
        @keyframes slideIn {
          from { transform: translateX(20px); opacity: 0; }
          to { transform: translateX(0); opacity: 1; }
        }
      `}</style>
    </div>
  );
}

/* ── APP ROOT ────────────────────────────────────────────────────── */
export default function App() {
  const [page,setPage]=useState(() => {
    if (typeof window === "undefined") return "home";
    const hashPage = window.location.hash.replace(/^#/, "");
    return hashPage === "training" || hashPage === "queue-v2" ? hashPage : "home";
  });
  useEffect(() => {
    if (typeof window === "undefined") return;
    const nextHash = page === "home" ? "" : `#${page}`;
    if (window.location.hash === nextHash) return;
    const nextUrl = `${window.location.pathname}${window.location.search}${nextHash}`;
    window.history.replaceState(null, "", nextUrl);
  }, [page]);
  if (page==="training") return <TrainingPage setPage={setPage} />;
  if (page==="queue-v2") return <QueueReviewPage setPage={setPage} />;
  return (
    <div style={{minHeight:"100vh",background:T.ink}}>
      <FloatingDemoBar />
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&display=swap');
        *{margin:0;padding:0;box-sizing:border-box;}
        body{font-family:'DM Sans',sans-serif;background:${T.ink};}
        ::-webkit-scrollbar{width:3px;}
        ::-webkit-scrollbar-track{background:transparent;}
        ::-webkit-scrollbar-thumb{background:${T.slate};border-radius:2px;}
        button,input,select,textarea{font-family:'DM Sans',sans-serif;}
      `}</style>
      {page!=="home"&&<Nav page={page} setPage={setPage}/>}
      {page==="home"&&<HomePage setPage={setPage}/>}
      {page==="operators"&&<OperatorsPage setPage={setPage}/>}
      {page==="vendors"&&<VendorsPage/>}
      {page==="pricing"&&<PricingPage setPage={setPage}/>}
      {page==="signup"&&<SignupPage/>}
    </div>
  );
}
